/**
 * Seed a believable working casebook. The runs are generated by the same
 * engine the app uses at runtime, so the long lists, dedupe counts and price
 * checks are internally consistent rather than hand-written fixtures.
 */

const DAY = 86_400_000;

function daysAgo(days, hours = 0) {
  return new Date(Date.now() - days * DAY - hours * 3_600_000).toISOString();
}

function addEvent(store, caseId, type, message, ts, { actor = 'Team', detail = null } = {}) {
  return store.addEvent({ caseId, type, actor, message, detail, ts });
}

function seedSourcesFromResult(store, result, createdAt) {
  const created = [];
  for (const discovery of result.discoveries) {
    const existing = store.findSourceByDomain(discovery.domain);
    if (existing) continue;
    const { source } = store.createSource({
      ...discovery,
      enabled: true,
      discovered_by: 'agent',
    });
    store.db
      .prepare('UPDATE sources SET created_at = ?, discovered_at = ? WHERE id = ?')
      .run(createdAt, createdAt, source.id);
    created.push(source);
  }
  return created;
}

function insertSearchRun(store, { caseRow, requirement, createdAt, iteration = 1 }) {
  const sources = store.listSources();
  const result = prepareSearch({ requirements: requirement, sources, caseIteration: iteration });
  seedSourcesFromResult(store, result, createdAt);
  const steps = describeSearchSteps(result);
  const durationMs = Math.max(24_000, steps.length * 1_850 + result.stats.extracted * 120);
  const startedAt = new Date(new Date(createdAt).getTime() + 12_000).toISOString();
  const finishedAt = new Date(new Date(startedAt).getTime() + durationMs).toISOString();
  const stats = {
    ...result.stats,
    coveredSources: result.sources.length,
    durationMs,
  };
  const run = store.createRun({
    caseId: caseRow.id,
    requirementsId: requirement.id,
    kind: 'search',
    iteration,
    status: 'running',
    createdAt,
  });
  store.updateRun(run.id, {
    status: 'completed',
    phase: 'complete',
    progress: 100,
    stats: JSON.stringify(stats),
    started_at: startedAt,
    finished_at: finishedAt,
    duration_ms: durationMs,
  });
  steps.forEach((step, index) => {
    const elapsed = Math.round((index / Math.max(1, steps.length - 1)) * durationMs);
    store.addRunStep(run.id, {
      seq: index + 1,
      phase: step.phase,
      level: step.level ?? 'info',
      message: step.message,
      detail: step.detail ?? null,
      ts: new Date(new Date(startedAt).getTime() + elapsed).toISOString(),
      elapsedMs: elapsed,
    });
  });
  store.insertListings(run.id, result.listings);
  store.touchSources(result.selectedSourceIds);
  return { run: store.getRun(run.id), result, stats };
}

function insertInventoryRun(store, { caseRow, requirement, check, createdAt, iteration = 1 }) {
  const listings = inventoryMatchesToListings(check, requirement);
  const market = canonicalMarket();
  for (const listing of listings) {
    listing.priceCheck = priceCheck(
      {
        id: listing.id,
        cluster: listing.fingerprint,
        city: listing.city,
        type: listing.type,
        transaction: listing.transaction,
        bedrooms: listing.bedrooms,
        areaM2: listing.areaM2,
        price: listing.price,
        features: listing.features,
        listedDaysAgo: 3,
      },
      market
    );
  }
  const priced = listings.filter((item) => item.priceCheck?.available);
  const aboveMarket = priced.filter((item) => item.priceCheck.verdict === 'above').length;
  const belowMarket = priced.filter((item) => item.priceCheck.verdict === 'below').length;
  const stats = {
    sourcesQueried: 2,
    queries: 4,
    extracted: listings.length,
    offBrief: Math.max(0, (check.checked || 0) - listings.length),
    duplicates: 0,
    uniqueListings: listings.length,
    longList: listings.length,
    discovered: 0,
    priceChecked: priced.length,
    aboveMarket,
    belowMarket,
    atMarket: priced.length - aboveMarket - belowMarket,
    coverage: requirement.regions?.join(' + ') || 'Algarve',
    iteration,
    comparisons: priced.reduce((sum, item) => sum + (item.priceCheck?.count || 0), 0),
    inventorySystem: 'Algarve Senior Living + Portugal Long Lets',
    durationMs: 9_400,
  };
  const createdAtIso = createdAt;
  const startedAt = new Date(new Date(createdAtIso).getTime() + 2_000).toISOString();
  const finishedAt = new Date(new Date(startedAt).getTime() + 9_400).toISOString();
  const run = store.createRun({
    caseId: caseRow.id,
    requirementsId: requirement.id,
    kind: 'inventory',
    iteration,
    status: 'running',
    createdAt: createdAtIso,
  });
  store.updateRun(run.id, {
    status: 'completed',
    phase: 'complete',
    progress: 100,
    stats: JSON.stringify(stats),
    started_at: startedAt,
    finished_at: finishedAt,
    duration_ms: 9_400,
  });
  const steps = [
    {
      phase: 'catalogue',
      message: 'Checked existing rental inventory',
      detail: 'Algarve Senior Living · Portugal Long Lets · availability and senior-friendly attributes',
    },
    {
      phase: 'filter',
      message: `Filtered ${check.checked ?? listings.length} inventory homes to the brief`,
      detail: 'Available status, location, budget and hard requirements',
    },
    {
      phase: 'rank',
      message: `Scored ${listings.length} suitable inventory homes`,
      detail: 'Lift, access, amenities and distance to medical services',
    },
    {
      phase: 'complete',
      message: 'Inventory matches ready for human review',
      detail: `${listings.length} homes · no external search needed`,
      level: 'success',
    },
  ];
  steps.forEach((step, index) => {
    const elapsed = Math.round((index / (steps.length - 1)) * 9_400);
    store.addRunStep(run.id, {
      seq: index + 1,
      phase: step.phase,
      level: step.level ?? 'info',
      message: step.message,
      detail: step.detail,
      ts: new Date(new Date(startedAt).getTime() + elapsed).toISOString(),
      elapsedMs: elapsed,
    });
  });
  store.insertListings(run.id, listings);
  return { run: store.getRun(run.id), listings, stats };
}

function buildRequirements(store, caseRow, brief, fields, { confirmed = true, daysOld = 1, by = 'Inês Duarte' } = {}) {
  const parsed = parseBrief(brief, fields);
  return store.addRequirements(
    caseRow.id,
    {
      ...parsed,
      notes: fields.notes ?? '',
    },
    {
      confirmed,
      confirmedBy: by,
      confirmedAt: confirmed ? daysAgo(daysOld) : null,
      createdBy: by,
      createdAt: daysAgo(daysOld + 1),
    }
  );
}

function pickListings(longList, count) {
  return longList.slice(0, count);
}

function rationaleFor(listing, position) {
  const check = listing.priceCheck;
  const priceText = check?.available
    ? check.verdict === 'below'
      ? `${Math.abs(check.deltaPct).toFixed(1)}% below the comparable median`
      : check.verdict === 'above'
        ? `${check.deltaPct.toFixed(1)}% above the comparable median`
        : 'inside the comparable-market corridor'
    : 'price evidence is thin';
  const openers = [
    'Best overall fit on location, budget and the must-haves.',
    'A quieter alternative with the same practical brief.',
    'The strongest view of the group, with a little more space.',
    'A newer building; worth seeing alongside the first choice.',
  ];
  return `${openers[position] ?? 'A credible alternative.'} ${priceText}.`;
}

